# owner: platform
import unittest

from hourglass.rounding import round_minutes, rounded_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_label_format(self):
        labels = rounded_labels([Span(540, 1035)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_rounds_to_nearest(self):
        labels = rounded_labels([Span(544, 1028)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        self.assertEqual(round_minutes(37, 15), 45)
        self.assertEqual(round_minutes(7, 15), 0)

    def test_whole_hour_label(self):
        labels = rounded_labels([Span(540, 600)], 30)
        self.assertEqual(labels, ["09:00-10:00 (1h 0m)"])

    def test_many_spans_keep_order(self):
        labels = rounded_labels([Span(600, 660), Span(60, 120)], 60)
        self.assertEqual(len(labels), 2)
        self.assertTrue(labels[0].startswith("10:00"))

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels([], step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(540, 545)], 15)
